<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0, viewport-fit=cover">
<meta name="claude:viewport-fit-sides" content="cover">
<title>KnoxBit</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Montserrat:ital,wght@0,600;0,700;0,800;0,900;1,700;1,800;1,900&family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
/* ===== KnoxBit — committed dark crypto-brand theme (navy + royal blue + gold) ===== */
/* Layout: sticky nav → hero → stacked full-width bands, each with an inner .wrap gutter */
:root{
  --bg:#04091c;           /* deep navy ground */
  --bg-2:#071233;         /* band tint */
  --panel:#0a1740;        /* card fill */
  --panel-2:#0d1f52;      /* elevated card */
  --blue:#1e5fe6;         /* royal blue */
  --blue-br:#4f9bff;      /* bright blue accent */
  --blue-glow:rgba(53,120,255,.45);
  --gold:#f5b301;         /* primary gold */
  --gold-lt:#ffd24a;      /* light gold */
  --gold-deep:#d98f00;
  --fg:#eaf1ff;           /* near-white text */
  --muted:#9ab0dc;        /* blue-grey muted */
  --line:rgba(102,140,220,.22);
  --line-gold:rgba(245,179,1,.35);
  color-scheme:dark;
  --maxw:1180px;
  --disp:'Montserrat',system-ui,sans-serif;
  --body:'Inter',system-ui,sans-serif;
}
*{box-sizing:border-box}
body{background:var(--bg);color:var(--fg);font-family:var(--body);line-height:1.6;
  -webkit-font-smoothing:antialiased;overflow-x:hidden}
/* notch band behind sticky header */
body::before{content:"";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);
  z-index:60;background:#030713}
img{max-width:100%;display:block}
a{color:inherit;text-decoration:none}
h1,h2,h3,h4{font-family:var(--disp);line-height:1.08;margin:0;text-wrap:balance}
p{margin:0}

.wrap{width:100%;max-width:var(--maxw);margin-inline:auto;
  padding-left:max(20px,env(safe-area-inset-left,0px));
  padding-right:max(20px,env(safe-area-inset-right,0px))}

/* ambient glows */
.band{position:relative}
.band-glow::before{content:"";position:absolute;inset:0;pointer-events:none;z-index:0;
  background:
    radial-gradient(60% 55% at 85% 0%, rgba(53,120,255,.14), transparent 60%),
    radial-gradient(50% 50% at 5% 100%, rgba(245,179,1,.08), transparent 60%)}
.band>.wrap{position:relative;z-index:1}

/* ===== eyebrow chevron pill (signature from deck) ===== */
.eyebrow{display:inline-flex;align-items:center;gap:.6em;font-family:var(--disp);font-weight:800;
  text-transform:uppercase;letter-spacing:.12em;font-size:clamp(11px,1.5vw,14px);
  color:#06122e;background:linear-gradient(180deg,var(--gold-lt),var(--gold) 60%,var(--gold-deep));
  padding:.55em 1.3em;border-radius:3px;
  clip-path:polygon(10px 0,100% 0,calc(100% - 10px) 100%,0 100%);
  box-shadow:0 0 22px rgba(245,179,1,.3)}
.eyebrow.ghost{color:var(--gold-lt);background:transparent;box-shadow:none;
  border:1px solid var(--line-gold);clip-path:none;border-radius:40px;padding:.5em 1.1em}
.chev{color:var(--gold)}

/* section scaffolding */
.sec{padding-block:clamp(56px,9vw,104px)}
.sec-head{display:flex;flex-direction:column;align-items:center;gap:18px;text-align:center;
  margin-bottom:clamp(36px,6vw,60px)}
.sec-title{font-weight:900;font-size:clamp(26px,5vw,46px);letter-spacing:-.01em}
.sec-title .g{color:var(--gold-lt)}
.sec-sub{color:var(--muted);max-width:60ch;font-size:clamp(15px,1.8vw,17px)}
.kicker{font-family:var(--disp);font-style:italic;font-weight:800;color:var(--blue-br);
  font-size:clamp(15px,2.2vw,20px);letter-spacing:.01em}

/* ===== NAV ===== */
.nav{position:sticky;top:env(safe-area-inset-top,0px);z-index:70;
  background:rgba(4,9,28,.82);backdrop-filter:blur(14px);
  border-bottom:1px solid var(--line)}
.nav-in{display:flex;align-items:center;justify-content:space-between;gap:16px;
  padding-block:12px}
.brand img{height:40px;width:auto}
.nav-links{display:flex;align-items:center;gap:30px}
.nav-links a{font-weight:600;font-size:14.5px;color:var(--muted);letter-spacing:.01em;
  transition:color .18s}
.nav-links a:hover{color:var(--fg)}
.btn{display:inline-flex;align-items:center;gap:.5em;font-family:var(--disp);font-weight:800;
  font-size:14px;letter-spacing:.04em;text-transform:uppercase;cursor:pointer;border:none;
  padding:.85em 1.7em;border-radius:6px;transition:transform .16s,box-shadow .16s}
.btn-gold{color:#06122e;background:linear-gradient(180deg,var(--gold-lt),var(--gold) 55%,var(--gold-deep));
  box-shadow:0 6px 24px rgba(245,179,1,.3)}
.btn-gold:hover{transform:translateY(-2px);box-shadow:0 10px 30px rgba(245,179,1,.45)}
.btn-blue{color:#fff;background:linear-gradient(180deg,var(--blue-br),var(--blue));
  box-shadow:0 6px 24px var(--blue-glow)}
.btn-blue:hover{transform:translateY(-2px);box-shadow:0 10px 30px var(--blue-glow)}
.btn-ghost{color:var(--fg);background:transparent;border:1.5px solid var(--line-gold)}
.btn-ghost:hover{border-color:var(--gold);color:var(--gold-lt)}
.btn-sm{padding:.6em 1.25em;font-size:12.5px}
.m-only{display:none}
.nav-cta{display:flex;align-items:center;gap:10px}
.burger{display:none;flex-direction:column;gap:5px;background:none;border:none;cursor:pointer;padding:8px}
.burger span{width:26px;height:2.5px;background:var(--gold-lt);border-radius:2px;transition:.2s}

/* ===== HERO ===== */
.hero{margin-top:calc(-1 * env(safe-area-inset-top,0px));
  padding-top:calc(env(safe-area-inset-top,0px) + clamp(48px,8vw,80px));
  padding-bottom:clamp(56px,9vw,96px);position:relative;overflow:hidden;
  background:
    radial-gradient(70% 90% at 80% -10%, rgba(53,120,255,.22), transparent 55%),
    radial-gradient(60% 80% at 0% 110%, rgba(245,179,1,.12), transparent 55%),
    linear-gradient(180deg,#061030,#04091c 70%)}
.hero-grid{display:grid;grid-template-columns:1.15fr .85fr;gap:48px;align-items:center}
.hero-tag{display:inline-block;margin:18px 0;font-family:var(--disp);font-weight:900;
  font-style:italic;font-size:clamp(13px,1.8vw,16px);letter-spacing:.14em;color:#06122e;
  background:linear-gradient(180deg,var(--gold-lt),var(--gold-deep));padding:.5em 1.4em;
  clip-path:polygon(12px 0,100% 0,calc(100% - 12px) 100%,0 100%);text-transform:uppercase}
.hero h1{font-weight:900;font-size:clamp(40px,8vw,78px);letter-spacing:-.02em;margin-bottom:10px}
.hero h1 .k{background:linear-gradient(180deg,#fff,#b9d2ff);-webkit-background-clip:text;
  background-clip:text;color:transparent}
.hero h1 .b{background:linear-gradient(180deg,var(--gold-lt),var(--gold-deep));
  -webkit-background-clip:text;background-clip:text;color:transparent}
.hero .welcome{font-family:var(--disp);font-weight:800;letter-spacing:.3em;color:var(--blue-br);
  font-size:clamp(13px,2vw,18px);text-transform:uppercase;margin-bottom:4px}
.hero-lead{color:#c7d6f5;font-size:clamp(16px,2vw,19px);max-width:46ch;margin:18px 0 28px}
.hero-cta{display:flex;flex-wrap:wrap;gap:14px;margin-bottom:26px}
.domain-chip{display:inline-flex;align-items:center;gap:.6em;border:1px solid var(--line-gold);
  background:rgba(0,0,0,.35);border-radius:40px;padding:.55em 1.3em;font-weight:700;
  letter-spacing:.03em;box-shadow:0 0 18px rgba(245,179,1,.18)}
.domain-chip .dot{color:var(--gold)}
.globe{color:var(--gold-lt)}

/* hero art */
.hero-art{position:relative;aspect-ratio:1/1;display:grid;place-items:center}
.hero-art .ring{position:absolute;inset:6%;border-radius:50%;
  background:radial-gradient(circle at 50% 40%,rgba(30,95,230,.3),rgba(4,9,28,0) 62%);
  border:1px solid rgba(79,155,255,.25);box-shadow:inset 0 0 60px rgba(53,120,255,.25)}
.hero-art .ring.r2{inset:18%;border-color:rgba(245,179,1,.22)}
.hero-art svg{position:relative;width:78%;height:78%}

/* ===== generic card ===== */
.card{background:linear-gradient(180deg,var(--panel),rgba(7,15,45,.6));
  border:1px solid var(--line);border-radius:16px;padding:26px;position:relative;
  transition:transform .2s,border-color .2s,box-shadow .2s}
.card:hover{transform:translateY(-4px);border-color:var(--line-gold);
  box-shadow:0 18px 44px rgba(3,8,26,.7)}
.ico{width:54px;height:54px;border-radius:12px;display:grid;place-items:center;flex:none;
  background:radial-gradient(circle at 32% 26%,rgba(245,179,1,.22),rgba(30,95,230,.14));
  border:1px solid var(--line-gold)}
.ico svg{width:28px;height:28px;stroke:var(--gold-lt);fill:none;stroke-width:1.9;
  stroke-linecap:round;stroke-linejoin:round}

/* about */
.about-lead{font-family:var(--disp);font-weight:800;font-size:clamp(20px,3vw,30px);
  line-height:1.25;max-width:24ch;margin:0 auto 42px;text-align:center}
.about-lead b{color:var(--gold-lt)}
.grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}
.card h3{font-size:18px;font-weight:800;margin:16px 0 8px}
.card p{color:var(--muted);font-size:15px}
.pillars{display:flex;flex-wrap:wrap;justify-content:center;gap:14px;margin-top:38px}
.pillar{display:inline-flex;align-items:center;gap:.6em;font-family:var(--disp);font-weight:800;
  letter-spacing:.04em;border:1px solid var(--line-gold);border-radius:40px;padding:.7em 1.5em;
  background:rgba(245,179,1,.06)}
.pillar svg{width:20px;height:20px;stroke:var(--gold-lt);fill:none;stroke-width:2}

/* mission & vision */
.mv{display:grid;grid-template-columns:1fr 1fr;gap:26px}
.mv .card{padding:32px}
.mv-head{display:flex;align-items:center;gap:14px;margin-bottom:18px}
.mv-head h3{font-size:clamp(20px,2.6vw,26px);font-weight:900;font-style:italic;text-transform:uppercase}
.mv-head h3 .g{color:var(--gold-lt)}
.mv .card p{color:#c2d2f2;font-size:15.5px;margin-bottom:14px}
.mv .card p:last-child{margin-bottom:0}

/* why — feature list */
.feat-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.feat{display:flex;gap:16px;align-items:flex-start;padding:20px 22px;border-radius:14px;
  background:linear-gradient(180deg,rgba(13,31,82,.55),rgba(7,15,45,.4));
  border:1px solid var(--line);transition:border-color .2s,transform .2s}
.feat:hover{border-color:var(--line-gold);transform:translateX(3px)}
.feat h4{font-size:17px;font-weight:800;color:var(--gold-lt);margin-bottom:4px;font-style:italic}
.feat p{color:var(--muted);font-size:14.5px}

/* how it works steps */
.steps{display:grid;grid-template-columns:repeat(5,1fr);gap:16px}
.step{text-align:center;padding:26px 18px;border-radius:16px;position:relative;
  background:linear-gradient(180deg,var(--panel),rgba(7,15,45,.5));border:1px solid var(--line)}
.step .num{width:48px;height:48px;margin:0 auto 14px;border-radius:50%;display:grid;place-items:center;
  font-family:var(--disp);font-weight:900;font-size:20px;color:#06122e;
  background:linear-gradient(180deg,var(--gold-lt),var(--gold-deep));
  box-shadow:0 0 20px rgba(245,179,1,.35)}
.step h4{font-size:15.5px;font-weight:800;margin-bottom:6px}
.step p{color:var(--muted);font-size:13.5px}

/* income types */
.inc-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}
.inc{padding:28px 24px}
.inc .ico{width:60px;height:60px;margin-bottom:16px}
.inc h3{font-weight:900;font-style:italic;font-size:19px}
.inc h3 .g{color:var(--gold-lt)}
.inc p{margin-top:8px}

/* packages */
.pkg-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:16px}
.pkg{position:relative;border-radius:14px;padding:22px 16px;text-align:center;
  background:linear-gradient(180deg,var(--panel-2),rgba(7,15,45,.5));
  border:1px solid var(--line);transition:transform .2s,border-color .2s,box-shadow .2s}
.pkg:hover{transform:translateY(-5px);border-color:var(--gold);
  box-shadow:0 16px 40px rgba(245,179,1,.18)}
.pkg .crown{width:34px;height:34px;margin:0 auto 10px}
.pkg .crown svg{width:100%;height:100%;fill:var(--gold-lt)}
.pkg .slot{font-family:var(--disp);font-weight:700;color:var(--muted);font-size:13px;
  letter-spacing:.08em;text-transform:uppercase}
.pkg .amt{font-family:var(--disp);font-weight:900;font-size:clamp(22px,3vw,30px);
  color:var(--gold-lt);margin-top:4px;font-variant-numeric:tabular-nums}
.pkg-note{text-align:center;color:var(--muted);margin-top:26px;font-size:14px}

/* referral highlight */
.ref{display:grid;grid-template-columns:1fr 1fr;gap:36px;align-items:center}
.ref-big{font-family:var(--disp);font-weight:900;font-size:clamp(90px,20vw,190px);line-height:.85;
  background:linear-gradient(180deg,var(--gold-lt),var(--gold-deep));-webkit-background-clip:text;
  background-clip:text;color:transparent;filter:drop-shadow(0 8px 30px rgba(245,179,1,.3))}
.ref-panel{text-align:center;padding:40px;border-radius:20px;
  background:radial-gradient(70% 90% at 50% 0%,rgba(30,95,230,.25),rgba(7,15,45,.5));
  border:1px solid var(--line)}
.ref h3{font-weight:900;font-style:italic;font-size:clamp(24px,4vw,38px);text-transform:uppercase;margin-bottom:16px}
.ref h3 .g{color:var(--gold-lt)}
.ref p{color:#c7d6f5;font-size:clamp(16px,2vw,19px)}
.ref .badge{display:inline-flex;align-items:center;gap:.5em;margin-top:22px;font-family:var(--disp);
  font-weight:900;font-size:20px;color:#06122e;padding:.6em 1.6em;border-radius:40px;
  background:linear-gradient(180deg,var(--gold-lt),var(--gold-deep))}

/* tables */
.tbl-wrap{overflow-x:auto;border-radius:16px;border:1px solid var(--line-gold)}
table{width:100%;border-collapse:collapse;min-width:420px;font-variant-numeric:tabular-nums}
thead th{font-family:var(--disp);font-weight:800;text-transform:uppercase;letter-spacing:.03em;
  font-size:13.5px;color:#06122e;padding:16px 18px;text-align:left;
  background:linear-gradient(180deg,var(--gold-lt),var(--gold) 60%,var(--gold-deep))}
tbody td{padding:13px 18px;border-top:1px solid var(--line);font-size:15px}
tbody tr:nth-child(odd){background:rgba(13,31,82,.4)}
.lv-name{font-weight:700}
.lv-pct{color:var(--gold-lt);font-weight:800}
.tbl-foot{display:flex;flex-wrap:wrap;gap:0;margin-top:14px;border-radius:14px;overflow:hidden;
  border:1px solid var(--line-gold)}
.tbl-foot div{flex:1;min-width:160px;padding:16px 20px;display:flex;align-items:center;
  justify-content:space-between;gap:12px;background:rgba(245,179,1,.08);font-family:var(--disp);
  font-weight:800;text-transform:uppercase;font-size:13px;letter-spacing:.03em}
.tbl-foot div span{font-size:26px;color:var(--gold-lt);font-weight:900}
.tbl-foot div+div{border-left:1px solid var(--line-gold)}

/* autopool */
.ap{display:grid;grid-template-columns:1fr 1fr;gap:30px;align-items:start}
.ap-list{display:flex;flex-direction:column;gap:14px}
.ap-item{display:flex;gap:16px;align-items:flex-start;padding:16px 20px;border-radius:12px;
  background:linear-gradient(90deg,rgba(13,31,82,.6),rgba(7,15,45,.3));border:1px solid var(--line)}
.ap-item h4{font-size:15.5px;font-weight:800;color:var(--gold-lt);margin-bottom:3px}
.ap-item p{color:var(--muted);font-size:14px}
.ap-right{text-align:center;padding:34px 26px;border-radius:20px;
  background:radial-gradient(70% 70% at 50% 20%,rgba(30,95,230,.28),rgba(7,15,45,.5));
  border:1px solid var(--line)}
.matrix-tag{font-family:var(--disp);font-weight:900;font-size:clamp(44px,9vw,76px);
  background:linear-gradient(180deg,var(--gold-lt),var(--gold-deep));-webkit-background-clip:text;
  background-clip:text;color:transparent;line-height:1}
.matrix-sub{font-family:var(--disp);font-weight:800;letter-spacing:.2em;color:var(--blue-br);
  text-transform:uppercase;font-size:14px;margin-top:4px}
.ap-30{margin-top:26px;font-family:var(--disp);font-weight:900;font-size:clamp(40px,8vw,66px);
  color:var(--gold-lt);line-height:1}
.ap-30 small{display:block;font-size:14px;letter-spacing:.14em;color:var(--fg);font-weight:800;
  margin-top:6px;text-transform:uppercase}
.ap-flow{display:flex;flex-wrap:wrap;gap:10px;margin-top:30px;justify-content:center}
.ap-flow .f{flex:1;min-width:150px;padding:16px;border-radius:12px;text-align:center;
  background:rgba(13,31,82,.55);border:1px solid var(--line);font-size:13px;color:var(--muted)}
.ap-flow .f b{display:block;color:var(--gold-lt);font-family:var(--disp);font-size:14px;margin-bottom:4px}

/* rewards */
.rw{display:grid;grid-template-columns:1.1fr .9fr;gap:30px;align-items:start}
.rw-pct{color:#fff;font-weight:800;background:linear-gradient(180deg,#7b2ff7,#4a1fb8);
  border-radius:40px;padding:.3em 1em;display:inline-block;min-width:64px;text-align:center;
  box-shadow:0 0 16px rgba(123,47,247,.4)}
.rw-key{display:flex;flex-direction:column;gap:14px}
.rw-key .card{padding:18px 20px;display:flex;gap:14px;align-items:flex-start}
.rw-key h4{font-size:15px;font-weight:800;color:var(--gold-lt);margin-bottom:3px}
.rw-key p{color:var(--muted);font-size:14px}

/* terms */
.terms{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}
.term{display:flex;align-items:center;gap:16px;padding:18px 22px;border-radius:14px;
  background:linear-gradient(90deg,rgba(13,31,82,.6),rgba(7,15,45,.35));border:1px solid var(--line)}
.term .ico{width:46px;height:46px}
.term .ico svg{width:24px;height:24px}
.term-txt{flex:1;min-width:0}
.term-txt h4{font-size:15px;font-weight:800;margin-bottom:2px}
.term-txt h4 .g{color:var(--gold-lt)}
.term-txt p{color:var(--muted);font-size:13.5px}
.term .val{font-family:var(--disp);font-weight:900;font-size:clamp(22px,3vw,30px);color:var(--gold-lt);
  flex:none;font-variant-numeric:tabular-nums}
.term.wide{grid-column:1/-1}

/* CTA / thank you */
.cta{text-align:center;padding:clamp(48px,8vw,88px) 0;position:relative;overflow:hidden;
  background:radial-gradient(60% 100% at 50% 0%,rgba(30,95,230,.28),transparent 60%),
    linear-gradient(180deg,#071233,#04091c)}
.cta h2{font-family:var(--disp);font-weight:900;font-size:clamp(34px,7vw,64px);
  background:linear-gradient(180deg,var(--gold-lt),var(--gold-deep));-webkit-background-clip:text;
  background-clip:text;color:transparent;filter:drop-shadow(0 6px 24px rgba(245,179,1,.3))}
.cta .sub{font-family:var(--disp);font-weight:800;letter-spacing:.14em;text-transform:uppercase;
  color:var(--fg);margin:12px 0 18px;font-size:clamp(14px,2vw,18px)}
.cta p{color:#c7d6f5;max-width:52ch;margin:0 auto 30px;font-size:clamp(15px,2vw,18px)}
.cta .hero-cta{justify-content:center}

/* footer */
.foot{border-top:1px solid var(--line);background:#030713;padding-block:44px 30px}
.foot-in{display:flex;flex-wrap:wrap;gap:30px;justify-content:space-between;align-items:flex-start}
.foot img{height:46px;margin-bottom:14px}
.foot .tag{color:var(--muted);max-width:34ch;font-size:14px}
.foot-links{display:flex;gap:40px;flex-wrap:wrap}
.foot-col h5{font-family:var(--disp);font-weight:800;text-transform:uppercase;letter-spacing:.08em;
  font-size:13px;color:var(--gold-lt);margin:0 0 12px}
.foot-col a{display:block;color:var(--muted);font-size:14px;padding:4px 0;transition:color .18s}
.foot-col a:hover{color:var(--fg)}
.foot-bottom{margin-top:34px;padding-top:22px;border-top:1px solid var(--line);
  display:flex;flex-wrap:wrap;gap:14px;justify-content:space-between;align-items:center;
  color:var(--muted);font-size:12.5px}
.foot-bottom .dchip{font-weight:700;color:var(--fg)}
.disc{color:#6f82a8;font-size:11.5px;max-width:70ch;margin-top:10px;line-height:1.5}

/* reveal (visible at rest; enhances only when JS present) */
.js .reveal{opacity:0;transform:translateY(22px);transition:opacity .6s ease,transform .6s ease}
.js .reveal.in{opacity:1;transform:none}
@media (prefers-reduced-motion:reduce){
  .js .reveal{opacity:1;transform:none;transition:none}
  *{scroll-behavior:auto!important}
}
html{scroll-behavior:smooth}
:focus-visible{outline:2px solid var(--gold-lt);outline-offset:3px;border-radius:4px}

/* ===== responsive ===== */
@media(max-width:1024px){
  .hero-grid{grid-template-columns:1fr;gap:30px}
  .hero-art{max-width:420px;margin:0 auto;order:-1}
  .steps{grid-template-columns:repeat(2,1fr)}
  .inc-grid{grid-template-columns:repeat(2,1fr)}
  .pkg-grid{grid-template-columns:repeat(3,1fr)}
}
@media(max-width:760px){
  .nav-links,.nav-cta .btn-ghost{display:none}
  .burger{display:flex}
  .nav.open .nav-links{display:flex;position:absolute;top:100%;left:0;right:0;flex-direction:column;
    gap:0;background:#071233;border-bottom:1px solid var(--line);padding:8px 20px 16px}
  .nav.open .nav-links a{padding:13px 0;border-bottom:1px solid var(--line);width:100%;font-size:16px}
  .nav.open .nav-links .m-only{display:block;color:var(--gold-lt);font-weight:800}
  .grid-3,.mv,.feat-grid,.ap,.rw,.terms{grid-template-columns:1fr}
  .ref{grid-template-columns:1fr;text-align:center}
  .ref-big{text-align:center}
  .term.wide{grid-column:auto}
}
@media(max-width:480px){
  .steps,.inc-grid,.pkg-grid{grid-template-columns:1fr 1fr}
  .tbl-foot div{min-width:100%}
}

/* ============== ANIMATION LAYER ============== */
/* reveal variants + stagger */
.js .reveal.rs{transform:scale(.9)}
.js .reveal.rl{transform:translateX(-42px)}
.js .reveal.rr{transform:translateX(42px)}
.js .reveal.in{transform:none}

/* hero particle network + floating coins */
#net{position:absolute;inset:0;width:100%;height:100%;z-index:0;pointer-events:none}
.hero .wrap{position:relative;z-index:2}
.coin{position:absolute;z-index:1;border-radius:50%;pointer-events:none;
  background:radial-gradient(circle at 34% 28%,#fff1c0,#f5b301 52%,#b9760a);
  box-shadow:0 8px 22px rgba(245,179,1,.4),inset 0 2px 7px rgba(255,255,255,.6),inset 0 -3px 7px rgba(140,80,0,.4);
  display:grid;place-items:center;color:#8a5a00;font-family:var(--disp);font-weight:900}
.coin::after{content:"$"}
.c1{width:48px;height:48px;left:3%;top:22%;font-size:20px;animation:bob 5.5s ease-in-out infinite}
.c2{width:30px;height:30px;left:11%;top:64%;font-size:13px;animation:bob 6.8s ease-in-out infinite .6s}
.c3{width:40px;height:40px;right:5%;bottom:14%;font-size:17px;animation:bob 6s ease-in-out infinite .3s}
.c4{width:24px;height:24px;right:17%;top:9%;font-size:11px;animation:bob 7.4s ease-in-out infinite 1s}
@keyframes bob{0%,100%{transform:translateY(0) rotate(-7deg)}50%{transform:translateY(-18px) rotate(7deg)}}

/* orbiting nodes on hero globe */
.orbit{position:absolute;inset:7%;border-radius:50%;animation:spin 15s linear infinite}
.orbit i{position:absolute;top:-6px;left:50%;width:13px;height:13px;margin-left:-6px;border-radius:50%;
  background:var(--gold-lt);box-shadow:0 0 16px var(--gold)}
.orbit.o2{inset:21%;animation:spin 10s linear infinite reverse}
.orbit.o2 i{width:10px;height:10px;background:var(--blue-br);box-shadow:0 0 16px var(--blue-br)}
@keyframes spin{to{transform:rotate(360deg)}}

/* hero chart grows / arrow draws in */
.hero-art rect{transform-box:fill-box;transform-origin:bottom;animation:grow .9s cubic-bezier(.2,.8,.2,1) both}
.hero-art rect:nth-of-type(1){animation-delay:.15s}
.hero-art rect:nth-of-type(2){animation-delay:.3s}
.hero-art rect:nth-of-type(3){animation-delay:.45s}
.hero-art rect:nth-of-type(4){animation-delay:.6s}
@keyframes grow{from{transform:scaleY(0)}to{transform:scaleY(1)}}
.hero-art .arrow{stroke-dasharray:360;stroke-dashoffset:360;animation:draw 1.3s ease-out .5s forwards}
@keyframes draw{to{stroke-dashoffset:0}}

/* marquee ticker */
.marquee{overflow:hidden;border-block:1px solid var(--line-gold);
  background:linear-gradient(90deg,#071233,#050d26,#071233);padding-block:14px}
.marquee-track{display:flex;width:max-content;animation:slide 30s linear infinite}
.marquee:hover .marquee-track{animation-play-state:paused}
.marquee span{display:inline-flex;align-items:center;white-space:nowrap;padding-right:40px;
  font-family:var(--disp);font-weight:800;text-transform:uppercase;letter-spacing:.12em;
  font-size:clamp(13px,1.8vw,16px);color:var(--fg)}
.marquee b{color:var(--gold);padding:0 22px;font-size:10px}
@keyframes slide{to{transform:translateX(-50%)}}

/* stats / count-up band */
.stats{padding-block:clamp(48px,8vw,80px);
  background:radial-gradient(70% 100% at 50% 0%,rgba(30,95,230,.16),transparent 60%),linear-gradient(180deg,#04091c,#050d26)}
.stats-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:16px}
.stat{text-align:center;padding:26px 14px;border-radius:16px;position:relative;overflow:hidden;
  background:linear-gradient(180deg,var(--panel),rgba(7,15,45,.5));border:1px solid var(--line);
  transition:transform .25s,border-color .25s,box-shadow .25s}
.stat:hover{transform:translateY(-5px);border-color:var(--line-gold);box-shadow:0 16px 40px rgba(245,179,1,.14)}
.stat .n{font-family:var(--disp);font-weight:900;font-size:clamp(30px,5vw,50px);line-height:1;
  background:linear-gradient(180deg,var(--gold-lt),var(--gold-deep));-webkit-background-clip:text;
  background-clip:text;color:transparent;font-variant-numeric:tabular-nums}
.stat .l{color:var(--muted);font-size:12.5px;text-transform:uppercase;letter-spacing:.06em;
  font-weight:600;margin-top:8px}
@media(max-width:860px){.stats-grid{grid-template-columns:repeat(3,1fr)}}
@media(max-width:480px){.stats-grid{grid-template-columns:repeat(2,1fr)}}

/* button shine sweep */
.btn{position:relative;overflow:hidden}
.btn::after{content:"";position:absolute;top:0;left:-130%;width:55%;height:100%;transform:skewX(-20deg);
  background:linear-gradient(100deg,transparent,rgba(255,255,255,.55),transparent);transition:left .6s ease}
.btn:hover::after{left:150%}

/* package gradient border on hover + gentle glow on hover */
.pkg::before{content:"";position:absolute;inset:0;border-radius:14px;padding:1.5px;pointer-events:none;
  background:linear-gradient(135deg,var(--gold-lt),transparent 42%,transparent 58%,var(--blue-br));
  -webkit-mask:linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);
  -webkit-mask-composite:xor;mask-composite:exclude;opacity:0;transition:opacity .3s}
.pkg:hover::before{opacity:1}
.pkg .crown svg{transition:transform .3s}
.pkg:hover .crown svg{transform:translateY(-3px) scale(1.12)}

/* ambient glow pulse behind section eyebrows */
.eyebrow{position:relative}
@keyframes glowpulse{0%,100%{box-shadow:0 0 18px rgba(245,179,1,.28)}50%{box-shadow:0 0 30px rgba(245,179,1,.5)}}
.eyebrow:not(.ghost){animation:glowpulse 3.4s ease-in-out infinite}

/* blockchain chain-link through the How-It-Works steps */
.steps{position:relative}
.steps::before{content:"";position:absolute;top:50px;left:9%;right:9%;height:3px;z-index:0;border-radius:3px;
  background:linear-gradient(90deg,transparent,var(--gold) 20%,var(--blue-br) 50%,var(--gold) 80%,transparent);
  background-size:220% 100%;animation:flow 3.2s linear infinite;opacity:.65}
.step{position:relative;z-index:1}
@keyframes flow{to{background-position:220% 0}}
@media(max-width:1024px){.steps::before{display:none}}

/* drifting tech grid behind stats + CTA (blockchain backdrop) */
.stats::before,.cta::before{content:"";position:absolute;inset:0;z-index:0;pointer-events:none;opacity:.6;
  background-image:linear-gradient(rgba(79,155,255,.06) 1px,transparent 1px),
    linear-gradient(90deg,rgba(79,155,255,.06) 1px,transparent 1px);
  background-size:42px 42px;animation:griddrift 20s linear infinite;
  -webkit-mask:radial-gradient(85% 85% at 50% 45%,#000,transparent);mask:radial-gradient(85% 85% at 50% 45%,#000,transparent)}
.stats>.wrap,.cta>.wrap{position:relative;z-index:1}
@keyframes griddrift{to{background-position:42px 42px}}

/* auth panels */
.auth{display:grid;grid-template-columns:1fr 1fr;gap:24px;max-width:860px;margin:0 auto}
.auth .card{padding:30px}
.auth h3{font-weight:900;font-style:italic;text-transform:uppercase;font-size:clamp(20px,3vw,26px);margin-bottom:6px}
.auth h3 .g{color:var(--gold-lt)}
.auth .sub{color:var(--muted);font-size:14px;margin-bottom:18px}
.field{display:flex;flex-direction:column;gap:6px;margin-bottom:14px}
.field label{font-size:12.5px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:var(--muted)}
.field input{background:rgba(4,9,28,.6);border:1px solid var(--line);border-radius:10px;padding:12px 14px;
  color:var(--fg);font-family:var(--body);font-size:15px;transition:border-color .2s,box-shadow .2s}
.field input:focus{outline:none;border-color:var(--gold);box-shadow:0 0 0 3px rgba(245,179,1,.15)}
.auth .btn{width:100%;justify-content:center;margin-top:6px}
.auth .alt{text-align:center;color:var(--muted);font-size:13px;margin-top:14px}
.auth .alt a{color:var(--gold-lt);font-weight:700}
.form-note{display:none;margin-top:12px;padding:10px 14px;border-radius:10px;font-size:13.5px;font-weight:600;
  background:rgba(30,95,230,.15);border:1px solid var(--line);color:#cfe0ff}
@media(max-width:760px){.auth{grid-template-columns:1fr}}

@media (prefers-reduced-motion:reduce){
  .coin,.orbit,.marquee-track,.hero-art rect,.hero-art .arrow,.eyebrow,
  .steps::before,.stats::before,.cta::before{animation:none!important}
  .hero-art rect{transform:none!important}
  .hero-art .arrow{stroke-dashoffset:0!important}
  .btn::after{display:none}
}
</style>

</head>
