<script>
document.body.classList.add('js');
// mobile nav
var nav=document.getElementById('nav'),burger=document.getElementById('burger');
burger.addEventListener('click',function(){
  var open=nav.classList.toggle('open');
  burger.setAttribute('aria-expanded',open);
});
nav.querySelectorAll('.nav-links a').forEach(function(a){
  a.addEventListener('click',function(){nav.classList.remove('open');burger.setAttribute('aria-expanded',false);});
});
var RM=window.matchMedia('(prefers-reduced-motion:reduce)').matches;
// reveal — visible at rest for no-JS/thumbnail; enhance in-view with stagger
(function(){
  var els=[].slice.call(document.querySelectorAll('.reveal'));
  // stagger by index among reveal siblings
  els.forEach(function(e){
    var p=e.parentElement;
    if(p){var sibs=[].slice.call(p.children).filter(function(x){return x.classList&&x.classList.contains('reveal');});
      var i=sibs.indexOf(e); if(i>0)e.style.transitionDelay=Math.min(i*70,460)+'ms';}
  });
  if(!('IntersectionObserver' in window)){els.forEach(function(e){e.classList.add('in');});return;}
  var io=new IntersectionObserver(function(ents){
    ents.forEach(function(en){if(en.isIntersecting){en.target.classList.add('in');io.unobserve(en.target);}});
  },{rootMargin:'0px 0px -8% 0px',threshold:.08});
  els.forEach(function(e){
    var r=e.getBoundingClientRect();
    if(r.top<window.innerHeight*0.92){e.classList.add('in');}else{io.observe(e);}
  });
})();

// count-up stats
(function(){
  var nums=[].slice.call(document.querySelectorAll('.stat .n:not(.notnum)'));
  function run(el){
    var to=parseFloat(el.getAttribute('data-to')),suf=el.getAttribute('data-suf')||'';
    if(RM){el.textContent=to+suf;return;}
    var start=null,dur=1500;
    function step(t){if(!start)start=t;var p=Math.min(1,(t-start)/dur);
      var e=1-Math.pow(1-p,3);el.textContent=Math.round(to*e)+suf;if(p<1)requestAnimationFrame(step);}
    requestAnimationFrame(step);
  }
  if(!('IntersectionObserver' in window)){nums.forEach(run);return;}
  var io=new IntersectionObserver(function(es){es.forEach(function(en){
    if(en.isIntersecting){run(en.target);io.unobserve(en.target);}});},{threshold:.5});
  nums.forEach(function(n){io.observe(n);});
})();

// auth forms (demo handling — wire to your platform backend)
(function(){
  function wire(fid,nid){
    var f=document.getElementById(fid),n=document.getElementById(nid); if(!f) return;
    f.addEventListener('submit',function(e){
      e.preventDefault();
      var ok=true;
      f.querySelectorAll('input[required]').forEach(function(i){
        if(!i.value.trim()){ok=false;i.style.borderColor='#e5484d';}else{i.style.borderColor='';}
      });
      if(!ok) return;
      if(n){n.style.display='block';}
    });
  }
  wire('form-signup','note-signup');
  wire('form-signin','note-signin');
})();

// hero particle network ("global community")
(function(){
  var c=document.getElementById('net'); if(!c||RM) return;
  var ctx=c.getContext('2d'),DPR=Math.min(2,window.devicePixelRatio||1),W,H,pts=[],raf;
  function size(){var r=c.parentElement.getBoundingClientRect();
    W=c.width=Math.max(1,r.width*DPR);H=c.height=Math.max(1,r.height*DPR);}
  size();
  var N=Math.max(26,Math.min(66,Math.round(W/DPR/20)));
  for(var i=0;i<N;i++)pts.push({x:Math.random()*W,y:Math.random()*H,
    vx:(Math.random()-.5)*.22*DPR,vy:(Math.random()-.5)*.22*DPR});
  var maxd=118*DPR;
  function draw(){
    ctx.clearRect(0,0,W,H);
    for(var i=0;i<pts.length;i++){var p=pts[i];p.x+=p.vx;p.y+=p.vy;
      if(p.x<0||p.x>W)p.vx*=-1;if(p.y<0||p.y>H)p.vy*=-1;}
    for(var i=0;i<pts.length;i++)for(var j=i+1;j<pts.length;j++){
      var a=pts[i],b=pts[j],dx=a.x-b.x,dy=a.y-b.y,d=Math.sqrt(dx*dx+dy*dy);
      if(d<maxd){ctx.strokeStyle='rgba(79,155,255,'+(1-d/maxd)*.33+')';ctx.lineWidth=DPR;
        ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();}}
    for(var i=0;i<pts.length;i++){var p=pts[i];ctx.beginPath();
      ctx.arc(p.x,p.y,1.7*DPR,0,6.3);ctx.fillStyle='rgba(245,179,1,.85)';ctx.fill();}
    raf=requestAnimationFrame(draw);
  }
  draw();
  window.addEventListener('resize',size);
  document.addEventListener('visibilitychange',function(){
    if(document.hidden){cancelAnimationFrame(raf);}else{cancelAnimationFrame(raf);draw();}});
})();
</script>

</body>
</html>